{
    /// <summary>
    /// Pays for upgrade of a regular gift that is owned by another user or channel chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> BuyGiftUpgradeAsync(MessageSender ownerId = default, string prepaidUpgradeHash = default, long starCount = default)
    {

           using var activity =  StartCallActivity("BuyGiftUpgradeAsync", typeof(BuyGiftUpgrade).FullName ?? "BuyGiftUpgradeAsync");

           try
           {
             return client.BuyGiftUpgradeAsync(ownerId, prepaidUpgradeHash, starCount);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
